SELECT p.id AS position_id, e.delivery_status, COUNT(*) AS n, MIN(e.price) AS min_price, MAX(e.price) AS max_price, MIN(e.observed_at) AS first_obs, MAX(e.observed_at) AS last_obs, p.stop_loss, p.take_profit, p.entry_price FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event e ON e.symbol = p.symbol AND e.observed_at BETWEEN p.opened_at AND p.closed_at WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id, e.delivery_status, p.stop_loss, p.take_profit, p.entry_price ORDER BY p.id, e.delivery_status;